import React, { useEffect, useState } from 'react';
import { api } from './api';
import './App.css';

function App() {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    // Качаем данные из бэкенда
    api.getProducts().then(data => setProducts(data));
  }, []);

  return (
    <div className="store">
      <header>
        <h1>Nail Professional Store</h1>
        <p>Всё для идеального маникюра</p>
      </header>
      
      <div className="grid">
        {products.map(p => (
          <div key={p.id} className="card">
            <div className="category-tag">{p.category}</div>
            <h3>{p.name}</h3>
            <p className="desc">{p.description}</p>
            <div className="bottom-info">
              <span className="price">{p.price} ₽</span>
              <span className="stock-count">В наличии: {p.stock}</span>
            </div>
            <button className="buy-btn">В корзину</button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
